#!/bin/zsh
# Compiles Shaders/Kernels.ci.metal into Sources/Kadr/KernelLibrary.swift: the metallib as base64 data.
# The generated file is committed, so building the app needs no Metal compiler (the Command Line Tools have
# none); run this after editing the kernels. Needs Xcode with the Metal Toolchain
# (xcodebuild -downloadComponent MetalToolchain).
set -e
cd "$(dirname "$0")/.."
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
# Stitchable kernels call into Core Image's own Metal library: linked with -framework CoreImage.
xcrun -sdk macosx metal -mmacosx-version-min=15.0 Shaders/Kernels.ci.metal -framework CoreImage -o "$TMP/k.metallib"
OUT=Sources/Kadr/KernelLibrary.swift
{
  echo "// Generated by tools/build-kernels.sh from Shaders/Kernels.ci.metal — do not edit."
  echo "import Foundation"
  echo ""
  echo "enum KernelLibrary {"
  echo "    static let data = Data(base64Encoded: \"\"\""
  base64 -i "$TMP/k.metallib" -b 120 | sed 's/^/        /'
  echo "        \"\"\", options: .ignoreUnknownCharacters)!"
  echo "}"
} > "$OUT"
echo "Ядра собраны: $OUT"
